  <path d="M161 41 Q189 48 208 67" fill="none" stroke="#ad4b39" strokeWidth="4"/>
  {[-20,-10,-7,-5,-3,0,3].map((n,i)=>{const a=(-143+i*17)*Math.PI/180;return <g key={n}><line x1={120+99*Math.cos(a)} y1={127+99*Math.sin(a)} x2={120+105*Math.cos(a)} y2={127+105*Math.sin(a)} stroke={n>=0?'#a34331':'#514d3c'} strokeWidth="1.4"/><text x={120+117*Math.cos(a)} y={129+117*Math.sin(a)} textAnchor="middle" fontSize="9" fill={n>=0?'#a34331':'#514d3c'}>{n>0?`+${n}`:n}</text></g>;})}
